mapper.update:
update chain_room
set status = 'PLAYING',
    started_date = now(),
    current_turn_member_id = #{currentTurnMemberId},
    current_turn_deadline = #{currentTurnDeadline}
where chain_room_id = #{chainRoomId}

update chain_room
set current_turn_member_id = #{currentTurnMemberId},
    current_turn_deadline = #{currentTurnDeadline}

        , last_chain_word_id = #{lastChainWordId}

where chain_room_id = #{chainRoomId}

update chain_room_member
set lives = #{lives},
    score = score + #{scoreDelta}
where chain_room_id = #{chainRoomId} and member_id = #{memberId}

update chain_room_member
set eliminated_yn = 'Y', eliminated_date = #{eliminatedDate}
where chain_room_id = #{chainRoomId} and member_id = #{memberId}

update chain_room_member
set final_rank = #{finalRank}
where chain_room_id = #{chainRoomId} and member_id = #{memberId}

mapper.select:
select count(*) > 0
from chain_room_member
where chain_room_id = #{chainRoomId} and member_id = #{memberId}

mapper.delete:
delete from chain_room_member
where chain_room_id in
#{id}
